mapper.sql:
s.dup_of_spot_id IS NULL
AND s.verify_status_cd <> 'REJECTED'
AND EXISTS (
    SELECT 1
    FROM spot_tag t
    WHERE t.spot_id = s.spot_id
      AND t.verify_status_cd <> 'REJECTED'
      AND t.tag_cd = #{tag}
      AND t.verify_status_cd = #{verifyStatus}
)

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM facility f
    WHERE f.mountain_id = #{mountainId}
      AND f.dup_of_facility_id IS NULL
      AND f.verify_status_cd <> 'REJECTED'
      AND f.fac_type_cd = #{type}
)

mapper.sql:
SELECT ST_Collect(e.geom) AS geom
FROM trail_edge e
WHERE e.mountain_id = #{mountainId}
  AND e.edge_id IN
    #{edgeId}
